/*
 * A306313  Numbers such that the product of their digits is equal to 10 times
 *          the sum of their prime factors, without multiplicity.
 * https://oeis.org/A306313
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  nonn, base, easy
 * Formula:   a(n) = nth smallest positive integer such that * product of its
 *            decimal digits equals 10 times the sum of its * distinct prime
 *            factors. The sequence is generated by * searching integers in
 *            ascending order
 * Range:     u8 none, u16 n <= 9, u32 n <= 37, u64 n <= 37, u128 n <= 37,
 *            big any n
 * Helpers:   digit_counts, digit_product, factor_u64, seq_alloc, seq_realloc
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

#include <stdbool.h>
#include "../utils/digit_counts.h"
#include "../utils/digit_product.h"
#include "../utils/factor_u64.h"
#include "../utils/seq_alloc.h"
#include "../utils/seq_realloc.h"

seq_t a(idx_t n)
{
    static seq_t *cache = NULL;
    static size_t cache_len = 0;
    static size_t cache_cap = 0;
    static uint64_t last_checked = 0;
    static bool initialized = false;

    if (!initialized) {
        cache_cap = 128;
        cache = seq_alloc(cache_cap);
        cache_len = 0;
        last_checked = 1583;            /* next number to test */
        initialized = true;
    }

    while (cache_len < (size_t)n) {
        ++last_checked;

        /* Quick digit filtering --------------------------------------------------- */
        unsigned char freq[10];
        digit_counts((seq_t)last_checked, freq);
        if (freq[0]) continue;                 /* no zero digits allowed */
        if (!freq[5]) continue;                /* at least one digit 5 needed */
        if (!(freq[2] || freq[4] || freq[6] || freq[8])) continue; /* at least one even non‑zero digit */

        /* Compute product of digits ----------------------------------------------- */
        seq_t prod = digit_product((seq_t)last_checked);

        /* Compute sum of distinct prime factors ------------------------------ */
        uint64_t primes[64];
        uint64_t exps[64];
        size_t cnt;
        factor_u64(last_checked, primes, exps, &cnt);
        if (cnt == 0) continue;                /* should not happen */

        seq_t sum = 0;
        for (size_t i = 0; i < cnt; ++i)
            sum += (seq_t)primes[i];

        /* Check the defining equation ------------------------------------------ */
        seq_t target = (seq_t)10 * sum;
        if (prod == target) {
            if (cache_len == cache_cap) {
                size_t new_cap = (cache_cap == 0) ? 16 : cache_cap * 2;
                seq_t *tmp = seq_realloc(cache, cache_cap, new_cap);
                if (!tmp) return 0;            /* allocation failed */
                cache = tmp;
                cache_cap = new_cap;
            }
            cache[cache_len++] = (seq_t)last_checked;
        }
    }

    return cache[(size_t)n - 1];
}
